package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.FilterOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CpioArchiveOutputStream.close()
 */
public class CpioArchiveOutputStream_close_TriageGen2Test {

    /**
     * Tests that calling close() when the stream is not yet closed 
     * works correctly and sets the closed state.
     */
    @Test
    public void testClose_WhenNotClosed_Success() throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (CpioArchiveOutputStream cos = new CpioArchiveOutputStream(bos)) {
            // The stream is currently open
            cos.close();
            // After calling close, subsequent calls should not throw exception 
            // (due to the 'if (!this.closed)' check)
            cos.close();
        }
        // If no exception is thrown, the logic for the first close call passed.
    }

    /**
     * Tests that calling close() multiple times does not trigger the super.close() 
     * logic more than once, effectively testing the branch 'if (!this.closed)'.
     */
    @Test
    public void testClose_MultipleCalls_DoesNotThrow() throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(bos);

        cos.close();
        cos.close();
        cos.close();

        // If we reached here, the 'if (!this.closed)' branch prevented redundant super.close() calls
    }

    /**
     * Tests that close() handles cases where the underlying stream throws an IOException.
     * This ensures we test the line containing super.close().
     */
    @Test(expected = IOException.class)
    public void testClose_WhenSuperCloseThrowsException() throws IOException {
        OutputStream errorStream = new OutputStream() {
            @Override
            public void write(int b) throws IOException {
                // No-op
            }

            @Override
            public void close() throws IOException {
                throw new IOException("Simulated close failure");
            }
        };

        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(errorStream);
        cos.close();
    }

    /**
     * Tests the interaction between close and other methods to ensure state management.
     */
    @Test(expected = IOException.class)
    public void testClose_AfterClose_WritingThrowsException() throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(bos);

        cos.close();

        // Writing to a closed stream should typically throw an IOException 
        // via the underlying stream or the internal state.
        cos.write(new byte[1], 0, 1);
    }
}
